aff(a){return"Channels: "+a},
gafg(){return"No channels selected"},
afw(a,b){return a+" (CC "+b+")"},
gxl(){return"None"},
gxm(){return"Pitch Bend"},
gxn(){return"Vibrato"},
gI9(){return"Glissando"},
