ga1k(){return"D\xe9filer automatiquement la liste lors de la r\xe9ception MIDI"},
gaoW(){return"Rack"},
gLf(){return"Ajouter un plugin"},
gaol(){return"GrooveForge Keyboard"},
gaom(){return"Synth\xe9 soundfont ou MIDI seul (Aucune) pour le c\xe2blage"},
gaoG(){return"Vocodeur"},
gaoH(){return"Synth\xe8se vocale par microphone (GFPA)"},
gaop(){return"Mode Jam"},
gaoq(){return"Verrouille la gamme d'un clavier sur l'harmonie d'un autre"},
gX_(){return"Supprimer le plugin"},
